import {
  getSportabaseLogoMarkup,
} from "./logo.js";

import {
  applyPreferences,
} from "./preferences.js";

import {
  installSettingsDrawer,
} from "./settings.js";

import {
  installWindowControls,
} from "./window-controls.js";

const OVERLAY_ID = "sportabase-root";

const SHELL_CLOSE_EVENT =
  "sportabase:before-close";

function notifySportabaseShellClosing(
  overlay
) {
  if (
    !overlay ||
    overlay.dataset.closeNotified ===
      "true"
  ) {
    return;
  }

  overlay.dataset.closeNotified =
    "true";

  overlay.dispatchEvent(
    new CustomEvent(
      SHELL_CLOSE_EVENT
    )
  );
}

function closeSportabaseShell(overlay) {
  if (
    !overlay ||
    overlay.dataset.closing === "true"
  ) {
    return;
  }

  notifySportabaseShellClosing(
    overlay
  );

  overlay.dataset.closing = "true";
  overlay.classList.remove("sb-is-open");
  overlay.classList.add("sb-is-closing");

  window.setTimeout(() => {
    overlay.remove();
  }, 180);
}

export function openSportabaseShell({
  mode = "article",
  preferences = {},
} = {}) {
  const existingOverlay =
    document.getElementById(
      OVERLAY_ID
    );

  if (existingOverlay) {
    notifySportabaseShellClosing(
      existingOverlay
    );

    existingOverlay.remove();
  }

  const modeLabel =
    mode === "video"
      ? "VIDEO INTELLIGENCE · YOUTUBE"
      : "ARTICLE INTELLIGENCE";

  const overlay =
    document.createElement("aside");

  overlay.id = OVERLAY_ID;
  overlay.className = "sb-overlay";

  overlay.setAttribute(
    "aria-label",
    "Sportabase intelligence panel"
  );

  overlay.innerHTML = `
    <header class="sb-header">
      <div class="sb-brand">
        ${getSportabaseLogoMarkup()}

        <div class="sb-brand-copy">
          <div class="sb-brand-title">
            Sportabase
          </div>

          <div
            class="sb-brand-mode"
            data-sb-mode-label
          >
            ${modeLabel}
          </div>
        </div>
      </div>

      <div class="sb-header-actions">
        <button
          class="sb-icon-button"
          type="button"
          data-sb-settings
          aria-label="Open settings"
          aria-expanded="false"
          title="Settings"
        >
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="1.8"
            stroke-linecap="round"
            stroke-linejoin="round"
            aria-hidden="true"
          >
            <path d="M4 7h10"></path>
            <path d="M18 7h2"></path>
            <circle cx="16" cy="7" r="2"></circle>

            <path d="M4 17h2"></path>
            <path d="M10 17h10"></path>
            <circle cx="8" cy="17" r="2"></circle>
          </svg>
        </button>

        <button
          class="sb-icon-button"
          type="button"
          data-sb-close
          aria-label="Close Sportabase"
          title="Close"
        >
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            aria-hidden="true"
          >
            <path d="M6 6l12 12"></path>
            <path d="M18 6L6 18"></path>
          </svg>
        </button>
      </div>
    </header>

    <main
      class="sb-content"
      data-sb-content
    ></main>
  `;

  const mountTarget =
    document.body ||
    document.documentElement;

  mountTarget.appendChild(overlay);

  const resolvedPreferences =
    applyPreferences(
      overlay,
      preferences
    );

  installSettingsDrawer({
    overlay,
    preferences: resolvedPreferences,
  });

  installWindowControls({
    overlay,
    preferences: resolvedPreferences,
  });

  overlay
    .querySelector("[data-sb-close]")
    ?.addEventListener("click", () => {
      closeSportabaseShell(overlay);
    });

  requestAnimationFrame(() => {
    overlay.classList.add("sb-is-open");
  });

  const content = overlay.querySelector(
    "[data-sb-content]"
  );

  const modeLabelElement =
    overlay.querySelector(
      "[data-sb-mode-label]"
    );

  return {
    overlay,
    content,

    onClose(callback) {
      if (
        typeof callback !==
        "function"
      ) {
        return () => {};
      }

      const listener = () => {
        callback();
      };

      overlay.addEventListener(
        SHELL_CLOSE_EVENT,
        listener,
        {
          once: true,
        }
      );

      return () => {
        overlay.removeEventListener(
          SHELL_CLOSE_EVENT,
          listener
        );
      };
    },

    close() {
      closeSportabaseShell(overlay);
    },

    setModeLabel(value) {
      if (modeLabelElement) {
        modeLabelElement.textContent =
          String(value || "");
      }
    },
  };
}
